function validate([processorTime, tasks]) {
  const n = processorTime.length;
  if (n < 1 || n > 25000) return 'processorTime needs 1 to 25000 values.';
  if (tasks.length !== 4 * n) return 'tasks must hold exactly 4 times as many values as processorTime.';
  if (processorTime.some(v => !Number.isInteger(v) || v < 0 || v > 1e9)) return 'Each processorTime value is an integer from 0 to 10^9.';
  if (tasks.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each task takes an integer time from 1 to 10^9.';
  return null;
}

