function minProcessingTime(processorTime, tasks) {
  const processors = [...processorTime].sort((a, b) => a - b);
  const jobs = [...tasks].sort((a, b) => b - a);
  let finish = 0;

  for (let i = 0; i < processors.length; i++) {
    const longest = jobs[4 * i];
    const done = processors[i] + longest;
    if (done > finish) {
      finish = done;
    }
  }
  return finish;
}

