function minProcessingTime(processorTime, tasks) {
  // Try every way to place the tasks on cores, tracking the latest finishing time.
  const n = processorTime.length;
  const used = new Array(n).fill(0);
  let best = Infinity;
  const place = (j, latest) => {
    if (latest >= best) return;
    if (j === tasks.length) { best = latest; return; }
    for (let p = 0; p < n; p++) {
      if (used[p] === 4) continue;
      used[p]++;
      place(j + 1, Math.max(latest, processorTime[p] + tasks[j]));
      used[p]--;
    }
  };
  place(0, 0);
  return best;
}

