function generate(rand, size) {
  const n = size === 'large' ? 500 : 1 + Math.floor(rand() * 3);
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    const processorTime = Array.from({ length: n }, () => pick(0, 1e9));
    const tasks = Array.from({ length: 4 * n }, () => pick(1, 1e9));
    return [processorTime, tasks];
  }
  // Small inputs use narrow ranges so equal times and ties show up, with an occasional extreme value.
  const span = [3, 10, 30][Math.floor(rand() * 3)];
  const processorTime = Array.from({ length: n }, () => (rand() < 0.1 ? 1e9 : pick(0, span)));
  const tasks = Array.from({ length: 4 * n }, () => (rand() < 0.1 ? 1e9 : pick(1, span)));
  return [processorTime, tasks];
}
